"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["38930"],{14798(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.alteracao_quebra_modelo_de_formulario","status":422,"titulo":"A altera\xe7\xe3o deixaria de valer um modelo de formul\xe1rio"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.alteracao_quebra_modelo_de_formulario","requisitos":["UNI-REQ-0159"],"oQueAconteceu":["O administrador enviou a nova defini\xe7\xe3o de um fato do cat\xe1logo (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`), mas um modelo de formul\xe1rio, ativo ou n\xe3o, usa este fato, e a defini\xe7\xe3o nova o deixaria inv\xe1lido, por exemplo por mudar o tipo de dado, o formato ou o escopo de um campo que o modelo vincula. A corre\xe7\xe3o da defini\xe7\xe3o de um fato \xe9 regra do UNI-REQ-0159, e a API recusa a altera\xe7\xe3o que deixaria inv\xe1lido algo que j\xe1 cita o fato, em vez de alter\xe1-lo em sil\xeancio. Nada \xe9 gravado: o fato continua com a defini\xe7\xe3o anterior. A recusa s\xf3 conta o que a altera\xe7\xe3o causa: o que o modelo j\xe1 tinha de inv\xe1lido antes n\xe3o entra.","A recusa vem na lista `errors` da resposta, com `field` igual a `citacoes.modelos.<c\xf3digo do modelo>`, uma entrada por modelo afetado. A mensagem cita o que deixaria de valer."],"comoResolver":["Escolha uma das sa\xeddas. Ajuste o item do modelo de formul\xe1rio citado para que ele valha com a defini\xe7\xe3o nova e reenvie a altera\xe7\xe3o; ou escolha outra defini\xe7\xe3o, que mantenha o modelo v\xe1lido. Desativar o modelo n\xe3o basta, porque os modelos inativos tamb\xe9m s\xe3o conferidos.","A defini\xe7\xe3o corrigida vale para os rascunhos e para os processos novos; a vers\xe3o j\xe1 publicada de um processo n\xe3o muda."],"ondeAparece":["Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);